import {heroAttributes,heroConfig,effectiveMaxHp} from './game.js';
import {sceneCopy} from './expedition-ui.js';
import {manualBattleBody} from './kolom-jrpg.js';
import {KOLOM_SCENES,kolomAvailable,kolomLocal} from './kolomenskaya.js';
import {ITEMS} from './data.js';
export function kolomEntry(s,{btn}){
 if(!kolomAvailable(s)&&s.interactiveMission?.id!=='kolomenskaya')return '';
 return '<section class="card dima-quest-card"><div class="dima-quest-intro"><div class="dima-quest-person"><img src="./kolom-scenes/dima-los.jpg" alt="Дима Лось — охрана Союза станций" width="76" height="76" style="object-fit:cover;border-radius:8px"><h3>Дима Лось</h3></div><div class="dima-quest-copy"><p class="subtitle">Союз станций · начальник охраны Технопарка</p><p>Коломенская захвачена скорпионами-пауками. Разведайте тоннели, найдите способ уничтожить гнёзда и освободите станцию.</p></div></div><p class="note gold">Награда за первое выполнение: 300 А и две случайные награды 7-го и 8-го уровней.</p>'+btn(s.interactiveMission?.id==='kolomenskaya'?'Продолжить очистку Коломенской':s.completedLocations?.kolomenskaya?'Очистка Коломенской':'Очистка Коломенской','kolomOpen','','full mission-start')+(kolomLocal()?'<p class="note">Подземная вылазка · Технопарк → Коломенская · локальный пробный проход</p>':'')+'</section>';
}
export function kolomBody(s,{btn,esc,health,heroPortrait,renderLog}){
 const a=s.interactiveMission;
 if(a?.id!=='kolomenskaya'){
  if(s.lastKolomMission&&!s.kolomPreparing){const r=s.lastKolomMission,rows=r.entries??[],heroes=r.heroes??[r.hero],xp=rows.length?rows.reduce((n,e)=>n+(e.xp??0),0):r.awardedXp??0,items=r.repeat?[]:Object.entries(r.loot??{}).map(([item,qty])=>({item,qty}));if(!r.repeat)items.push(...(r.rewardItems??[]));items.push(...(r.grenadeRefunds??[]));if(r.questReward&&!r.repeat)items.push(r.questReward);return '<div class="eyebrow">ОЧИСТКА КОЛОМЕНСКОЙ / ОТЧЁТ</div><h3>'+(r.success?'Коломенская освобождена':r.dead?'Отряд погиб':'Возвращение без завершения')+'</h3><p class="note">'+(r.repeat?'Тестовый повтор: сохранён только опыт.':'Награды уже получены. Герои восстанавливаются после вылазки.')+'</p><div class="report-stats"><div><strong>+'+xp+'</strong><small>ОПЫТА НА ОТРЯД</small></div><div><strong>+'+(r.repeat?0:(r.money??0)/10)+' А</strong><small>ПОЛУЧЕНО</small></div><div><strong>'+heroes.length+'</strong><small>УЧАСТНИКОВ</small></div></div><div class="recovery-party">'+heroes.map(member=>{const row=rows.find(e=>e.id===member.id);return '<div class="card recovery-hero"><div class="row">'+heroPortrait(member)+'<strong>'+esc(member.name)+'</strong></div>'+health(member)+'<p class="subtitle">+'+(row?.xp??r.awardedXp??0)+' опыта · '+(row?.dead?'Погиб':'Облучение +'+(row?.radiation??0))+'</p></div>';}).join('')+'</div><h3>Получено</h3><div class="loot">'+(items.map(e=>'<div>'+esc(ITEMS[e.item]?.name??e.item)+(e.quality?' +'+e.quality:'')+' ×'+e.qty+'</div>').join('')||'<p class="muted">Без находок.</p>')+'</div>'+btn('Вернуться на станцию','kolomClose','','full expedition-result-return')+'<details class="battle-log result-log"><summary>Ход вылазки</summary>'+(r.events??[]).map(t=>'<p>'+esc(t)+'</p>').join('')+'</details>';}

  if(!s.kolomQuestAccepted)return '<img src="./kolom-scenes/dima-los.jpg" alt="Дима Лось" width="96" height="96" style="border-radius:8px"><h3>Дима Лось · Очистка Коломенской</h3><p>«С Коломенской снова лезут пауки. Охрана сдерживает их у Технопарка, но гнёзда нужно уничтожить. Разведайте тоннели и очистите станцию. Возьмите огонь и лекарства — лёгкой прогулки не будет».</p><p class="note gold">Награда: 300 А и две случайные награды 7-го и 8-го уровней. Только за первое выполнение.</p>'+btn('Принять задание','kolomAccept','','full mission-start');
  const heroes=s.heroes.filter(h=>!h.dead&&!h.unconscious&&!h.job&&!h.needsAdventureRest&&!h.adventureCooldownUntil);
  const selected=s.kolomPreparationIds??[heroes[0]?.id,heroes[1]?.id];
  const picked=selected.map(id=>heroes.find(h=>h.id===id)).filter(Boolean),front=picked.some(h=>h.id===s.kolomFrontHeroId)?s.kolomFrontHeroId:picked[0]?.id;
  const option=h=>esc(h.name)+' · ур. '+h.level+' · HP '+Math.round(h.hp)+' / '+Math.round(effectiveMaxHp(h));
  const summary=h=>{const a=heroAttributes(h),cfg=heroConfig(s,h).hero;return '<section class="card"><div class="row">'+heroPortrait(h)+'<strong>'+esc(h.name)+' · ур. '+h.level+'</strong></div>'+health(h)+'<p class="subtitle">СИЛ '+a.strength+' · ЛОВ '+a.agility+' · ИНТ '+a.intelligence+' · ВОС '+a.perception+' · РАД '+(cfg.radiationProtection??0)+'</p><p class="subtitle">Защита: физ. '+cfg.armor+' · терм. '+cfg.thermalArmor+' · Молотовы '+(h.molotovs??0)+'</p></section>';};
  return '<img class="interactive-stage-image" src="./kolom-scenes/prep.jpg" alt="Выход из Технопарка"><h3>Подготовка к Коломенской</h3><p class="note">Рекомендуется 7-й уровень, физическая и РАД-защита. Могут пригодиться коктейли Молотова.</p><label>Первый участник</label><select id="kolom-hero" class="hero-select">'+heroes.map(h=>'<option value="'+esc(h.id)+'" '+(selected[0]===h.id?'selected':'')+'>'+option(h)+'</option>').join('')+'</select><label>Второй участник</label><select id="kolom-second" class="hero-select"><option value="" '+(!selected[1]?'selected':'')+'>Идти одному — крайне опасно</option>'+heroes.filter(h=>h.id!==selected[0]).map(h=>'<option value="'+esc(h.id)+'" '+(selected[1]===h.id?'selected':'')+'>'+option(h)+'</option>').join('')+'</select>'+picked.map(summary).join('')+'<label>Кто идёт первым</label><select id="kolom-front" class="hero-select">'+picked.map(h=>'<option value="'+esc(h.id)+'" '+(front===h.id?'selected':'')+'>'+esc(h.name)+'</option>').join('')+'</select><p class="note">Обычные враги атакуют ведущего; при засаде и нападении толпы цели выбираются среди всего отряда.</p><p><label><input id="kolom-risk" type="checkbox" '+(s.kolomRiskConfirmed?'checked':'')+'> Подтверждаю риск для героя ниже 7-го уровня</label></p><div class="button-row">'+btn('Снарядить лекарствами','kolomPack','data-category="medicine"','secondary')+btn('Снарядить гранатами','kolomPack','data-category="grenades"','secondary')+'</div>'+btn('Подтвердить отправку · без фильтров','kolomStart',picked.length?'':'disabled','full mission-start');
 }
 const party=a.heroIds.map(id=>s.heroes.find(h=>h.id===id)),h=party.find(h=>h.id===a.selectedHealHeroId)??party.find(h=>h.hp>0)??party[0],total=key=>party.filter(h=>h.hp>0).reduce((n,h)=>n+(h[key]??0),0),node=a.node,scene=KOLOM_SCENES[node],b=(text,choice,disabled=false)=>btn(text,'kolomChoice',`data-node="${node}" data-choice="${choice}" data-target="${h.id}" ${disabled?'disabled':''}`,'full secondary');
 if(node==='combat'&&a.combat?.manual&&a.combat.manualStarted)return manualBattleBody(a,party);
 const report=node==='recovery'&&a.combat&&!a.combat.reportSeen;let choices='';
 if(report&&a.combat.manual)return manualBattleBody(a,party)+b('Перейти к лечению','report');
 if(node==='fork')choices=b('Прислушаться к чутью · ВОС 15','sense',a.senseUsed)+b('Левый тоннель','left')+b('Правый тоннель','right');
 if(['dry1','dry2','clear','blaze'].includes(node))choices=b('Продолжить путь','forward');
 if(['corpse','lair'].includes(node))choices=b('Обыскать останки','search')+b('Пройти мимо','skip');
 if(node==='anomaly')choices=b(party.some(member=>['medium','heavy'].includes(ITEMS[member.body]?.armorClass))?'Спрятаться за вагонеткой · ИНТ 18, затем ЛОВ 13':'Убежать от аномалии','avoid');
 if(node==='wet')choices=b('Идти дальше · участок 4 РАД','forward')+b('Вернуться к развилке','back');
 if(['worm','boss'].includes(node))choices=b(node==='boss'?'Начать бой':'Вступить в бой','fight');
 if(node==='station')choices=b('Пробиваться и искать решение','enter');
 if(node==='pressure')choices=(a.swarmTurns??5)>0?b('Стрелять и искать решение · ИНТ 14','think')+(a.ideas>=1?b('Отогнать гранатой','grenade',!['grenades','tinGrenades','lu216Grenades','radioactiveGrenades','dynamites'].some(k=>total(k)>0))+b('Использовать Молотов · −1 шт.','molotov',!total('molotovs')):'')+(a.ideas>=2?b('Использовать тяжёлое оружие','heavy',!party.some(member=>member.hp>0&&ITEMS[member.rangedWeapon]?.usesHeavyAmmo&&member.heavyAmmo>0)):''):'';
 if(node==='pressure'&&(a.swarmIntAttempts??0)>=2)choices+=b('Потратить 1000 А · это крайний вариант! · бой с 50 пауками','shootSwarm',s.money<10000);
 if(node==='fire'){const fc=a.fireDemonstration==='flame'?9:10,mc=a.fireDemonstration==='molotov'?9:10;choices=(a.swarmTurns??5)>0?b('Спалить гнёзда · −'+fc+' зарядов огнемёта или −'+mc+' Молотовых','burn',party.filter(h=>h.hp>0&&ITEMS[h.rangedWeapon]?.flame).reduce((n,h)=>n+(h.heavyAmmo??0),0)<fc&&total('molotovs')<mc):'';if((a.swarmIntAttempts??0)>=2)choices+=b('Потратить 1000 А · это крайний вариант! · бой с 50 пауками','shootSwarm',s.money<10000);}
 if(node==='casualty')choices=b('Сбежать с выжившим, бросив поверженного','escape')+b('Драться до последнего','fight');
 if(node==='combat'&&a.combat?.manual)choices=b('Начать бой','manual');
 else if(node==='combat')choices=a.combat.enemies.some(e=>e.kolomQueen)?b('Следующий ход','turn')+b('Разыграть бой до исхода','auto'):b('Начать бой','auto');
 if(node==='recovery'&&a.afterRecovery==='escape')choices=b('Вернуться на станцию и лечиться','continue');
 else if(node==='recovery')choices='<p class="note recovery-target">Лечим: <strong>'+esc(h.name)+'</strong></p><p class="subtitle">Лекарства из запасов всего отряда</p>'+[['doctorKit','doctorKits'],['medicKit','medicKits'],['dressingKit','dressingKits'],['bandage','bandages']].filter(([,key])=>total(key)>0).map(([id,key])=>b(ITEMS[id].name+' · '+total(key),'heal:'+id)).join('')+(party.some(h=>h.hp>0&&['medic','doctor'].includes(h.profession))?b('Лечение специалистом · −1 Силы','treatment',a.treatmentUsed)+b('Снять 1–3 дозы яда · −1 Силы','antidote',a.treatmentUsed||!h.poisonDoses):'')+b('Продолжить путь','continue');
 if(report)choices=b('Перейти к лечению','report');
 if(node==='cleanup')choices=b('Осмотреть и дочистить станцию','search');
 if(node==='final')choices=b('Завершить вылазку и сдать задание','finish');
 const fight=a.combat,art=node==='combat'?'combat-'+(fight.enemies.some(e=>e.kolomQueen)?'queen':fight.enemies.some(e=>e.kolomSlime)?'worm':'spiders'):['recovery','casualty'].includes(node)?'recovery':node;

 const title=(node==='combat'||report)?'Бой с '+(fight.enemies.some(e=>e.kolomQueen)?'Маткой Коломенской':fight.enemies.some(e=>e.kolomSlime)?'червём':'пауками'):scene[1];
 const portraits='<div class="recovery-party" role="group" aria-label="Участники вылазки">'+party.map(member=>'<button type="button" class="offer recovery-hero '+(member.id===h.id?'selected':'')+'" aria-pressed="'+(member.id===h.id)+'" data-action="kolomChoice" data-node="'+node+'" data-choice="pick" data-target="'+member.id+'"><span class="row">'+heroPortrait(member)+'<strong>'+esc(member.name)+'</strong></span>'+health(member)+(member.poisonDoses?'<span class="subtitle">Отравлен · '+member.poisonDoses+'</span>':'')+'</button>').join('')+'</div>';
 const battle=(report||node==='combat'&&fight.status!=='pending')?'<section class="battle-log result-log">'+(node==='combat'&&fight.enemies.some(e=>e.kolomQueen)?'<p>Порядок ходов: '+fight.order.map(x=>esc(x.name)).join(' → ')+'</p>':'')+renderLog(fight.events)+'</section>'+(report?'<p class="note gold">Противники повержены.</p><p class="note">Опыт за бой: '+a.combatXp+' на отряд · по '+Math.round(a.combatXp/party.length*10)/10+' базового опыта каждому. Личные бонусы учитываются при завершении вылазки.</p>':''):'';
 const journal=a.events.length>(a.sceneLogStart??0)?'<details class="battle-log result-log" open><summary>Ход вылазки · пояснения и броски</summary>'+a.events.slice(a.sceneLogStart??0).map(t=>'<p>'+esc(t)+'</p>').join('')+'</details>':'';
 const swarm=a.swarmAlert?'<div class="kolom-swarm-alert" role="status"><strong>Пауков сотни. Одиночные выстрелы не останавливают поток.</strong>'+(['pressure','fire'].includes(node)?'<p>До окружения: '+(a.swarmTurns??5)+' / 5 ходов</p><progress max="5" value="'+(a.swarmTurns??5)+'"></progress><p>'+((a.swarmTurns??5)===0?'Позиция потеряна: отступить или потратить 1000 А на бой до смерти.':(a.swarmTurns??5)<=1?'Пауки на броне':(a.swarmTurns??5)<=3?'Вы окружены':'Рой приближается')+'</p>':'')+'</div>':'';
 return swarm+'<img class="interactive-stage-image" src="./kolom-scenes/'+art+'.jpg" alt="'+esc(title)+'"><h3 class="expedition-scene-title">'+esc(title)+'</h3>'+sceneCopy(report?'Бой завершён — можно перейти к восстановлению.':node==='combat'?'Противники преграждают путь — приготовьтесь к бою.':scene[2],esc)+''+portraits+battle+journal+'<div class="research-options">'+choices+b('Отступить на станцию','retreat')+'</div>';
}
